examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
    MonarchText(text = {{lines.0}}, style = MonarchTextStyle.Subheading)
    MonarchText(text = {{lines.1}}, style = MonarchTextStyle.Body)
    MonarchText(text = {{lines.2}}, style = MonarchTextStyle.Label)
    MonarchText(text = {{lines.3}}, style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted)
}

examples.code:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
    MonarchText(text = "Large lead text for a short introduction.", style = MonarchTextStyle.Subheading)
    MonarchText(text = "Base body text for descriptions and paragraphs.", style = MonarchTextStyle.Body)
    MonarchText(text = "Small text for dense lists and table cells.", style = MonarchTextStyle.Label)
    MonarchText(text = "Extra small meta text, such as a timestamp.", style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted)
}
